import 'dart:convert';

import 'data.dart';

class RequestDetailsResponse {
  String? message;
  bool? hasNegotiation;
  bool? hasIndicators;
  bool? hasEconomicData;
  RequestData? data;

  RequestDetailsResponse({
    this.message,
    this.data,
    this.hasEconomicData,
    this.hasIndicators,
    this.hasNegotiation,
  });

  factory RequestDetailsResponse.from(Map<String, dynamic> data) {
    return RequestDetailsResponse(
      message: data['message'] as String?,
      hasNegotiation: data['has_negotiation'] as bool?,
      hasIndicators: data['has_indicators'] as bool?,
      hasEconomicData: data['has_economic_data'] as bool?,
      data:
          data['data'] == null
              ? null
              : RequestData.(
                data['data'] as Map<String, dynamic>,
              ),
    );
  }

  Map<String, dynamic>
  () {
    return {
      'message': message,
      'has_economic_data': hasEconomicData,
      'has_indicators': hasIndicators,
      'has_negotiation': hasNegotiation,
      'data':
          data?.(),
    };
  }

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [RequestDetailsResponse].
  factory RequestDetailsResponse.fromJson(String data) {
    return RequestDetailsResponse.from(
      json.decode(data) as Map<String, dynamic>,
    );
  }

  /// `dart:convert`
  ///
  /// Converts [RequestDetailsResponse] to a JSON string.
  String toJson() => json.encode(
    (),
  );
}
